import sys

def at_most(a, m):
    if m <= 0:
        return 0
    cnt = {}
    l = 0
    res = 0
    for r, x in enumerate(a):
        cnt[x] = cnt.get(x, 0) + 1
        while len(cnt) > m:
            y = a[l]
            cnt[y] -= 1
            if cnt[y] == 0:
                del cnt[y]
            l += 1
        res += r - l + 1
    return res

def main():
    data = sys.stdin.read().split()
    n, k = int(data[0]), int(data[1])
    a = [int(x) for x in data[2:2 + n]]
    print(n * (n + 1) // 2 - at_most(a, k - 1))

main()

